-- Starter widgets, so a fresh marketplace is not empty.
-- Owned by a curator page whose edit token is a fixed, public, non-secret value.

values ('starters', '00000000-0000-4000-8000-000000000000', 'mymainpage', '{}'::jsonb, '[]'::jsonb)
on conflict (slug) do nothing;

on conflict (author_slug, title) do update
  set description = excluded.description,
      tags = excluded.tags,
      spec = excluded.spec;

