values
  ('starters', 'mymainpage', 'To-do', 'Tasks with a done counter and progress bar.', '✅', '{productivity,lists}', '{"kind":"custom","id":"todo-a7j761","title":"To-do","icon":"✅","span":1,"state":{"draft":"","items":[]},"body":[{"t":"row","gap":2,"children":[{"t":"input","bind":"state.draft","placeholder":"Add a task…","grow":true,"onSubmit":[{"a":"push","path":"state.items","value":{"id":"{{uid()}}","text":"{{state.draft}}","done":false}},{"a":"set","path":"state.draft","value":""}]},{"t":"button","label":"Add","variant":"primary","on":[{"a":"push","path":"state.items","value":{"id":"{{uid()}}","text":"{{state.draft}}","done":false}},{"a":"set","path":"state.draft","value":""}]}]},{"t":"progress","value":"{{count(state.items,''done'')}}","max":"{{len(state.items)}}","label":"{{count(state.items,''done'')}} of {{len(state.items)}} done"},{"t":"repeat","each":"state.items","as":"item","empty":"Nothing here yet.","children":[{"t":"row","gap":2,"align":"between","children":[{"t":"checkbox","bind":"state.items[{{itemIndex}}].done"},{"t":"text","value":"{{item.text}}","grow":true,"strikeWhen":"item.done"},{"t":"button","label":"✕","variant":"ghost","on":{"a":"removeAt","path":"state.items","index":"{{itemIndex}}"}}]}]}]}'::jsonb),
  ('starters', 'mymainpage', 'Habit tracker', 'Seven-day grid, one row per habit, streak count per row.', '🔥', '{habits,health}', '{"kind":"custom","id":"habit-mhnm3r","title":"Habit tracker","icon":"🔥","span":2,"state":{"draft":"","days":["Mon","Tue","Wed","Thu","Fri","Sat","Sun"],"habits":[{"id":"h1","text":"Read 20 min","marks":[false,false,false,false,false,false,false]},{"id":"h2","text":"Workout","marks":[false,false,false,false,false,false,false]}]},"body":[{"t":"row","gap":2,"children":[{"t":"input","bind":"state.draft","placeholder":"New habit…","grow":true,"onSubmit":[{"a":"push","path":"state.habits","value":{"id":"{{uid()}}","text":"{{state.draft}}","marks":[false,false,false,false,false,false,false]}},{"a":"set","path":"state.draft","value":""}]},{"t":"button","label":"Add","variant":"primary","on":[{"a":"push","path":"state.habits","value":{"id":"{{uid()}}","text":"{{state.draft}}","marks":[false,false,false,false,false,false,false]}},{"a":"set","path":"state.draft","value":""}]}]},{"t":"repeat","each":"state.habits","as":"habit","empty":"Add a habit to start a streak.","children":[{"t":"row","gap":2,"align":"between","children":[{"t":"text","value":"{{habit.text}}","grow":true},{"t":"row","gap":1,"children":[{"t":"repeat","each":"state.days","as":"day","children":[{"t":"button","label":"{{habit.marks[dayIndex] ? ''●'' : ''○''}}","variant":"ghost","on":{"a":"toggle","path":"state.habits[{{habitIndex}}].marks[{{dayIndex}}]"}}]}]},{"t":"badge","value":"{{count(habit.marks)}}/7","tone":"accent"},{"t":"button","label":"✕","variant":"ghost","on":{"a":"removeAt","path":"state.habits","index":"{{habitIndex}}"}}]}]},{"t":"divider"},{"t":"text","value":"{{join(state.days,''  '')}}","muted":true,"size":"xs"}]}'::jsonb),
  ('starters', 'mymainpage', 'Pomodoro', '25/5/15 focus timer that counts finished sessions.', '🍅', '{focus,time}', '{"kind":"custom","id":"pomodoro-tbyhj2","title":"Pomodoro","icon":"🍅","span":1,"state":{"left":1500,"running":false,"done":0},"body":[{"t":"timer","bind":"state.left","running":"state.running","onDone":[{"a":"set","path":"state.running","value":false},{"a":"inc","path":"state.done","by":1},{"a":"sound","name":"ding"}]},{"t":"row","gap":2,"children":[{"t":"button","label":"{{state.running ? ''Pause'' : ''Start''}}","variant":"primary","grow":true,"on":{"a":"toggle","path":"state.running"}},{"t":"button","label":"Reset","variant":"ghost","on":[{"a":"set","path":"state.left","value":1500},{"a":"set","path":"state.running","value":false}]}]},{"t":"row","gap":2,"children":[{"t":"button","label":"25m","variant":"ghost","grow":true,"on":{"a":"set","path":"state.left","value":1500}},{"t":"button","label":"5m","variant":"ghost","grow":true,"on":{"a":"set","path":"state.left","value":300}},{"t":"button","label":"15m","variant":"ghost","grow":true,"on":{"a":"set","path":"state.left","value":900}}]},{"t":"stat","label":"Sessions finished","value":"{{state.done}}"}]}'::jsonb),
