  ('starters', 'mymainpage', 'Water', 'Glasses per day against a goal.', '💧', '{health}', '{"kind":"custom","id":"water-x8m8kn","title":"Water","icon":"💧","span":1,"state":{"glasses":0,"goal":8},"body":[{"t":"stat","label":"Today","value":"{{state.glasses}} / {{state.goal}} glasses"},{"t":"progress","value":"{{state.glasses}}","max":"{{state.goal}}"},{"t":"row","gap":2,"children":[{"t":"button","label":"+1 glass","variant":"primary","grow":true,"on":{"a":"inc","path":"state.glasses","by":1}},{"t":"button","label":"−","variant":"ghost","on":{"a":"set","path":"state.glasses","value":"{{max(0, state.glasses - 1)}}"}},{"t":"button","label":"Reset","variant":"ghost","on":{"a":"set","path":"state.glasses","value":0}}]}]}'::jsonb),
  ('starters', 'mymainpage', 'Spending', 'Log spending against a monthly budget.', '💸', '{money}', '{"kind":"custom","id":"expenses-7n473x","title":"Spending","icon":"💸","span":1,"state":{"label":"","amount":"","items":[],"budget":500},"body":[{"t":"stat","label":"Spent this month","value":"{{fixed(sum(state.items,''amount''),2)}}","hint":"budget {{state.budget}}"},{"t":"progress","value":"{{sum(state.items,''amount'')}}","max":"{{state.budget}}"},{"t":"row","gap":2,"children":[{"t":"input","bind":"state.label","placeholder":"What for?","grow":true},{"t":"input","bind":"state.amount","placeholder":"0","inputType":"number"},{"t":"button","label":"Add","variant":"primary","on":[{"a":"push","path":"state.items","value":{"id":"{{uid()}}","text":"{{state.label}}","amount":"{{num(state.amount)}}","day":"{{today()}}"}},{"a":"set","path":"state.label","value":""},{"a":"set","path":"state.amount","value":""}]}]},{"t":"repeat","each":"state.items","as":"item","empty":"No spending logged.","children":[{"t":"row","align":"between","gap":2,"children":[{"t":"text","value":"{{item.text}}","grow":true},{"t":"text","value":"{{fixed(item.amount,2)}}","muted":true},{"t":"button","label":"✕","variant":"ghost","on":{"a":"removeAt","path":"state.items","index":"{{itemIndex}}"}}]}]}]}'::jsonb),
  ('starters', 'mymainpage', 'Reading list', 'Save links and articles, tick them off when read.', '📚', '{reading,lists}', '{"kind":"custom","id":"reading-7wzuyo","title":"Reading list","icon":"📚","span":1,"state":{"draft":"","items":[]},"body":[{"t":"row","gap":2,"children":[{"t":"input","bind":"state.draft","placeholder":"Title or link…","grow":true,"onSubmit":[{"a":"push","path":"state.items","value":{"id":"{{uid()}}","text":"{{state.draft}}","done":false}},{"a":"set","path":"state.draft","value":""}]},{"t":"button","label":"Save","variant":"primary","on":[{"a":"push","path":"state.items","value":{"id":"{{uid()}}","text":"{{state.draft}}","done":false}},{"a":"set","path":"state.draft","value":""}]}]},{"t":"repeat","each":"state.items","as":"item","empty":"Nothing saved yet.","children":[{"t":"row","gap":2,"align":"between","children":[{"t":"checkbox","bind":"state.items[{{itemIndex}}].done"},{"t":"text","value":"{{item.text}}","grow":true,"strikeWhen":"item.done"},{"t":"button","label":"✕","variant":"ghost","on":{"a":"removeAt","path":"state.items","index":"{{itemIndex}}"}}]}]},{"t":"text","value":"{{count(state.items,''done'')}} finished","muted":true,"size":"xs"}]}'::jsonb),
  ('starters', 'mymainpage', 'Mood log', 'One tap a day, with a running log.', '🌤️', '{journal,health}', '{"kind":"custom","id":"mood-0aucgi","title":"Mood log","icon":"🌤️","span":1,"state":{"entries":[]},"body":[{"t":"row","gap":2,"children":[{"t":"button","label":"😄","variant":"ghost","grow":true,"on":{"a":"push","path":"state.entries","value":{"id":"{{uid()}}","text":"😄","day":"{{today()}}"}}},{"t":"button","label":"🙂","variant":"ghost","grow":true,"on":{"a":"push","path":"state.entries","value":{"id":"{{uid()}}","text":"🙂","day":"{{today()}}"}}},{"t":"button","label":"😐","variant":"ghost","grow":true,"on":{"a":"push","path":"state.entries","value":{"id":"{{uid()}}","text":"😐","day":"{{today()}}"}}},{"t":"button","label":"😔","variant":"ghost","grow":true,"on":{"a":"push","path":"state.entries","value":{"id":"{{uid()}}","text":"😔","day":"{{today()}}"}}}]},{"t":"repeat","each":"state.entries","as":"entry","empty":"Tap a face to log how today feels.","children":[{"t":"row","align":"between","gap":2,"children":[{"t":"text","value":"{{entry.text}}  {{entry.day}}","grow":true},{"t":"button","label":"✕","variant":"ghost","on":{"a":"removeAt","path":"state.entries","index":"{{entryIndex}}"}}]}]}]}'::jsonb),
